def patch(src: str) -> str:
    for old, new, label in REPLACEMENTS:
        src = replace_once(src, old, new, label)
    if MARKER not in src:
        src = src.rstrip("\n") + "\n\n# " + MARKER + "\n"
    return src


TARGETS = (("vllm_gaudi", "v1/spec_decode/hpu_eagle.py", patch),)

